from aide import L, st, e, v, d, ch, li, od

UNIT = ("Précision", "🎯", "Choisir le mot exact et la nuance juste.", [

L("🔬", "Quasi-synonymes et connotations",
  "Choisir entre des mots proches selon leur connotation.",
  [st("🔬", "Des mots au sens proche portent des jugements différents. thin (neutre), slim (positif), skinny (souvent négatif)."),
   st("⚖️", "stubborn (têtu, négatif) / determined (déterminé, positif) / persistent (neutre ou positif)."),
   st("💲", "cheap (bon marché, parfois de mauvaise qualité) / inexpensive (abordable, neutre) / affordable (accessible, positif)."),
   st("🧠", "persuade (convaincre d’AGIR) / convince (convaincre de CROIRE) : She persuaded me to come. He convinced me that it was true.")],
  [e("🏃", "She’s slim and athletic.", "Elle est mince et athlétique."),
   e("😤", "He’s so stubborn — he never changes his mind.", "Il est tellement têtu, il ne change jamais d’avis."),
   e("💪", "She’s determined to finish the marathon.", "Elle est déterminée à finir le marathon."),
   e("🏷️", "It’s an affordable option for families.", "C’est une option abordable pour les familles."),
   e("🗣️", "She persuaded me to apply for the job.", "Elle m’a persuadé de postuler.")],
  [v("🏃", "slim / skinny", "mince / maigrichon", "slim (positif), skinny (péjoratif)"),
   v("😤", "stubborn / determined", "têtu / déterminé", "stubborn (négatif)"),
   v("🏷️", "cheap / affordable", "bon marché / abordable", "affordable housing"),
   v("🗣️", "persuade / convince", "persuader (d’agir) / convaincre (de croire)", "persuade someone to…"),
   v("🎯", "connotation", "connotation", "a negative connotation"),
   v("👃", "smell / scent / stink", "odeur / parfum / puanteur", "the scent of roses")],
  [d("Editor", "You wrote that the product is « cheap ».", "Tu as écrit que le produit est « cheap »."),
   d("Writer", "Yes, it costs only twenty dollars.", "Oui, il ne coûte que vingt dollars."),
   d("Editor", "« Cheap » can suggest poor quality. Try « affordable ».", "« Cheap » peut suggérer une mauvaise qualité. Essaie « affordable »."),
   d("Writer", "Good point. And « skinny jeans » is fine?", "Bon point. Et « skinny jeans », c’est correct?"),
   d("Editor", "Yes — in fashion, « skinny » is neutral!", "Oui, en mode, « skinny » est neutre!")],
  "Les connotations changent avec le contexte : « skinny » est péjoratif pour une personne, mais neutre pour des jeans ou un café (a skinny latte = au lait écrémé).",
  [ch("Positive way to describe a thin person: ___", ["skinny", "slim", "bony"], 1, "slim = mince (positif)."),
   ch("She never gives up. She’s very ___. (positif)", ["stubborn", "determined", "obstinate"], 1, "determined = positif."),
   ch("The government wants more ___ housing.", ["cheap", "affordable", "cheaply"], 1, "affordable = abordable (positif)."),
   ch("He ___ me to try sushi. (il m’a amené à agir)", ["convinced", "persuaded", "argued"], 1, "persuade to + verbe."),
   li("It’s an affordable option.", ["It’s an affordable option.", "It’s a cheap option.", "It’s an available option."], 0, "affordable = abordable."),
   od("She persuaded me to apply for the job", "Elle m’a persuadé de postuler", "persuade someone to + verbe.")]),

L("🎚️", "Changer de registre",
  "Réécrire un même message dans plusieurs registres.",
  [st("🎚️", "Quatre registres : familier (casual), neutre, formel, académique. Le même message change de mots, de structure et de longueur."),
   st("🧢", "Familier : contractions, phrasal verbs, mots courts. « We need to sort this out ASAP. »"),
   st("👔", "Formel : mots latins, passif, pas de contractions. « This matter requires immediate attention. »"),
   st("🎓", "Académique : nominalisation, nuance, impersonnel. « The issue warrants prompt consideration. »")],
  [e("🧢", "Can you get back to me soon?", "Peux-tu me revenir rapidement?"),
   e("🙂", "Could you reply as soon as possible?", "Pourrais-tu répondre dès que possible?"),
   e("👔", "I would appreciate a prompt response.", "J’apprécierais une réponse rapide."),
   e("🧢", "The meeting got moved to Friday.", "La réunion a été déplacée à vendredi."),
   e("👔", "The meeting has been rescheduled to Friday.", "La réunion a été reportée à vendredi.")],
  [v("🧢", "sort out", "régler (familier)", "Let’s sort it out."),
   v("👔", "resolve", "résoudre (formel)", "to resolve the issue"),
   v("🧢", "get back to", "revenir à quelqu’un", "I’ll get back to you."),
   v("👔", "respond", "répondre (formel)", "Please respond by Friday."),
   v("🎓", "warrant", "justifier, mériter", "This warrants attention."),
   v("👔", "reschedule", "reporter, replanifier", "We need to reschedule.")],
  [d("Casual", "Hey, the deal fell through. We gotta find another supplier.", "Hé, l’entente est tombée à l’eau. Faut trouver un autre fournisseur."),
   d("Neutral", "The agreement didn’t go ahead, so we need a new supplier.", "L’entente ne s’est pas concrétisée, donc il nous faut un nouveau fournisseur."),
   d("Formal", "The agreement was not finalized; consequently, an alternative supplier must be identified.", "L’entente n’a pas été finalisée; par conséquent, un autre fournisseur doit être trouvé."),
   d("Coach", "Same message, three registers!", "Même message, trois registres!")],
  "Un bon test : lis ton texte à voix haute en imaginant ton destinataire. Si tu ne le dirais pas devant lui, change de registre.",
  [ch("Formal version of « get back to me »: ___", ["respond", "come back", "reply me back"], 0, "respond (formel)."),
   ch("Casual version of « resolve the issue »: ___", ["sort it out", "address the matter", "rectify it"], 0, "sort it out (familier)."),
   ch("Formal: « The meeting has been ___ to Friday. »", ["got moved", "rescheduled", "pushed"], 1, "rescheduled (formel)."),
   ch("Academic: « This issue ___ further research. »", ["warrants", "wants", "needs bad"], 0, "warrant = justifier."),
   li("I would appreciate a prompt response.", ["I would appreciate a prompt response.", "I would appreciate a prompt reply back.", "I’d appreciate a quick response."], 0, "Registre formel."),
   od("The meeting has been rescheduled to Friday", "La réunion a été reportée à vendredi", "Registre formel.")]),

L("🗡️", "Les figures de style",
  "Reconnaître et utiliser les procédés rhétoriques de l’anglais.",
  [st("🔁", "Allitération : répétition d’un son. « Dunkin’ Donuts », « Big Bad Wolf ». Très utilisée en publicité."),
   st("🎈", "Hyperbole : exagération. « I’ve told you a million times! » / Litote : « not bad » = très bien."),
   st("3️⃣", "La règle de trois (tricolon) : « Veni, vidi, vici », « Faster, stronger, better ». Rythme et mémorisation."),
   st("❓", "Question rhétorique : sans attendre de réponse. « Who doesn’t want to save money? »")],
  [e("🍩", "Coca-Cola, PayPal, Best Buy: brands love alliteration.", "Coca-Cola, PayPal, Best Buy : les marques adorent l’allitération."),
   e("🎈", "I’ve told you a million times!", "Je te l’ai dit mille fois!"),
   e("😏", "Not bad for a first try!", "Pas mal pour un premier essai! (= très bien)"),
   e("3️⃣", "Our service is fast, friendly and free.", "Notre service est rapide, chaleureux et gratuit."),
   e("❓", "Who doesn’t love a long weekend?", "Qui n’aime pas une longue fin de semaine?")],
  [v("🔁", "alliteration", "allitération", "a catchy alliteration"),
   v("🎈", "hyperbole", "hyperbole", "That’s a hyperbole."),
   v("😏", "litotes / understatement", "litote", "« Not bad » is a litotes."),
   v("3️⃣", "rule of three", "règle de trois", "Use the rule of three."),
   v("❓", "rhetorical question", "question rhétorique", "It was a rhetorical question."),
   v("🪞", "metaphor / simile", "métaphore / comparaison", "« As brave as a lion » is a simile.")],
  [d("Speechwriter", "The ending needs more punch.", "La fin manque de punch."),
   d("CEO", "What do you suggest?", "Que suggères-tu?"),
   d("Speechwriter", "A rule of three: « We will build, grow and lead. »", "Une règle de trois : « Nous allons bâtir, croître et mener. »"),
   d("CEO", "And a rhetorical question to start?", "Et une question rhétorique pour commencer?"),
   d("Speechwriter", "« Who said we couldn’t do it? » Perfect.", "« Qui a dit que nous n’y arriverions pas? » Parfait.")],
  "La règle de trois est partout dans les discours anglophones : trois adjectifs, trois exemples, trois promesses. Deux, c’est faible; quatre, c’est trop long.",
  [ch("« Fast, friendly and free » uses ___.", ["the rule of three", "a rhetorical question", "litotes"], 0, "Tricolon."),
   ch("« I’m so hungry I could eat a horse » is a(n) ___.", ["hyperbole", "litotes", "alliteration"], 0, "Exagération : hyperbole."),
   ch("« Peter Piper picked a peck of pickled peppers » is ___.", ["alliteration", "hyperbole", "a metaphor"], 0, "Répétition du son p."),
   ch("« Not bad at all! » (= excellent) is an example of ___.", ["understatement", "hyperbole", "sarcasm"], 0, "Litote / understatement."),
   li("Who doesn’t love a long weekend?", ["Who doesn’t love a long weekend?", "Who don’t love a long weekend?", "Who doesn’t love a lone weekend?"], 0, "Question rhétorique."),
   od("Our service is fast friendly and free", "Notre service est rapide, chaleureux et gratuit", "Règle de trois.")]),

L("🧱", "Grammaire de haut niveau",
  "Maîtriser les structures les plus sophistiquées.",
  [st("🔄", "Conditionnels inversés sans if : Had I known, I would have come. Were it not for your help, … Should it rain, …"),
   st("🧱", "Groupes nominaux complexes : « a recently published, widely cited study on climate migration »."),
   st("✂️", "Ellipse avancée : She can speak French, and so can her brother. I didn’t want to go, but I had to (go)."),
   st("🎩", "Structures littéraires : So beautiful was the view that… / Much as I admire him, … (bien que je l’admire)")],
  [e("🔙", "Had I known, I would have come.", "Si j’avais su, je serais venu."),
   e("🙏", "Were it not for your help, we would have failed.", "Sans ton aide, nous aurions échoué."),
   e("📚", "It’s a recently published, widely cited study.", "C’est une étude récemment publiée et largement citée."),
   e("🌄", "So beautiful was the view that we stayed for hours.", "La vue était si belle que nous sommes restés des heures."),
   e("🤝", "Much as I admire him, I can’t agree.", "Bien que je l’admire, je ne peux pas être d’accord.")],
  [v("🔙", "Had I known", "Si j’avais su", "Had I known, I’d have helped."),
   v("🙏", "Were it not for", "Sans, n’eût été", "Were it not for you…"),
   v("🌧️", "Should it…", "Si jamais il…", "Should it snow, we’ll cancel."),
   v("🤝", "Much as…", "Bien que, autant…", "Much as I like it, …"),
   v("📚", "widely cited", "largement cité", "a widely cited paper"),
   v("✂️", "ellipsis", "ellipse", "Avoid repetition with ellipsis.")],
  [d("Professor", "How would you rephrase « If I had known about the delay »?", "Comment reformulerais-tu « If I had known about the delay »?"),
   d("Student", "« Had I known about the delay »?", "« Had I known about the delay »?"),
   d("Professor", "Excellent. And « If it weren’t for the funding »?", "Excellent. Et « If it weren’t for the funding »?"),
   d("Student", "« Were it not for the funding ».", "« Were it not for the funding »."),
   d("Professor", "Perfect. Very elegant in academic writing.", "Parfait. Très élégant en rédaction universitaire.")],
  "« Had I known » correspond au français soutenu « Eussé-je su » ou plus simplement « Si j’avais su ». Réserve-le à l’écrit soigné et aux discours.",
  [ch("___ I known, I would have called.", ["Had", "If had", "Have"], 0, "Inversion : Had I known."),
   ch("___ it not for the rain, we’d have gone.", ["Were", "Was", "Had"], 0, "Were it not for…"),
   ch("So tired ___ that she fell asleep at dinner.", ["she was", "was she", "she has"], 1, "Inversion après So + adjectif."),
   ch("___ as I like him, I don’t trust him.", ["Much", "So", "Very"], 0, "Much as = bien que."),
   li("Had I known, I would have come.", ["Had I known, I would have come.", "If I knew, I would come.", "Had I know, I would have come."], 0, "Had + participe passé."),
   od("Were it not for your help we would have failed", "Sans ton aide, nous aurions échoué", "Were it not for…")]),

L("🧭", "Nuances de modalité",
  "Exprimer le degré exact de certitude et d’obligation.",
  [st("🧭", "Certitude graduée : will certainly > will probably > may well > might > could conceivably (à la rigueur) > is unlikely to."),
   st("📜", "Obligation graduée : must / have to > should / ought to > might want to (tu pourrais vouloir, conseil très doux)."),
   st("🎓", "Écriture académique : These findings may suggest… / It could be argued that… / This would appear to indicate…"),
   st("🫱", "Politesse : You might want to check the figures (= vérifie les chiffres, sans brusquer).")],
  [e("🎯", "The project will almost certainly be delayed.", "Le projet sera presque certainement retardé."),
   e("🤔", "This could conceivably work, but I doubt it.", "Ça pourrait à la rigueur fonctionner, mais j’en doute."),
   e("📊", "These results would appear to support the hypothesis.", "Ces résultats sembleraient appuyer l’hypothèse."),
   e("🫱", "You might want to double-check those figures.", "Tu voudrais peut-être revérifier ces chiffres."),
   e("📜", "Applicants must submit all documents by May 1.", "Les candidats doivent soumettre tous les documents d’ici le 1er mai.")],
  [v("🎯", "almost certainly", "presque certainement", "It will almost certainly rain."),
   v("🤔", "conceivably", "à la rigueur", "It could conceivably happen."),
   v("📊", "would appear to", "semblerait", "It would appear to be true."),
   v("🫱", "might want to", "voudrait peut-être (conseil doux)", "You might want to rest."),
   v("📜", "ought to", "devrait", "You ought to apologize."),
   v("🎓", "It could be argued that", "On pourrait soutenir que", "It could be argued that…")],
  [d("Reviewer", "Your conclusion says the drug « cures » the disease.", "Ta conclusion dit que le médicament « guérit » la maladie."),
   d("Researcher", "The results were very positive.", "Les résultats étaient très positifs."),
   d("Reviewer", "You might want to soften that. « The results would appear to suggest an improvement. »", "Tu voudrais peut-être nuancer. « Les résultats sembleraient suggérer une amélioration. »"),
   d("Researcher", "Fair enough. It could be argued that more trials are needed.", "C’est juste. On pourrait soutenir qu’il faut plus d’essais.")],
  "Quand un supérieur anglophone dit « You might want to… », ce n’est pas une option : c’est une demande polie!",
  [ch("Your boss says « You might want to revise this ». It means ___.", ["please revise it", "don’t revise it", "it’s optional"], 0, "Demande polie."),
   ch("The results would ___ to support the theory.", ["appear", "seem as", "look"], 0, "would appear to."),
   ch("It could ___ argued that the policy failed.", ["be", "being", "been"], 0, "It could be argued that…"),
   ch("Strongest certainty: ___", ["might", "will almost certainly", "could conceivably"], 1, "will almost certainly."),
   li("You might want to double-check those figures.", ["You might want to double-check those figures.", "You must double-check those figures.", "You might want to double-check those fingers."], 0, "Conseil très poli."),
   od("These results would appear to support the hypothesis", "Ces résultats sembleraient appuyer l’hypothèse", "Modalité académique.")]),
])
